    bezout: "В каждой строке r = s·a + t·b, поэтому последний ненулевой остаток даёт соотношение Безу: {g} = {s}·{a} + {t}·{b}.",
    dioSolvable: "НОД({a}, {b}) = {g} делит {c}, поэтому целых решений бесконечно много; соседние отличаются на ({dx}, {dy}). Зелёное — ближайшее к началу координат.",
