    grid: "Каждая категория на своей строке: Название: элемент, элемент, элемент — во всех поровну, от трёх до шести элементов, от двух до четырёх категорий; категория чисел (годы, цены) упорядочивается. Подсказки, по одной на строку: Аня = бигль, Аня ≠ 2009, Молли < Тоби (раньше), Рекс = бигль + 1 (на один позже), Боря ≠ бигль ≠ 2009 (все разные), {Дима, Сэм} = {2006, колли} (по одному на каждого), соединяются словами and, or, not и →. Пройди по шагам, чтобы увидеть, как решается: «остался один», перенос отметок пары ●, каждая подсказка и предположение, ведущее к противоречию.",
