    square: "Одно категорическое суждение — Все / Ни один / Некоторые / Некоторые … не, как в силлогизмах, или просто буква A, E, I или O, — истинное или ложное. Квадрат показывает, что это значит для трёх других суждений с теми же терминами и почему; под ним — обращение, превращение и противопоставление. По Аристотелю ни один термин не пуст и все четыре связи действуют; в современном прочтении — только противоречие.",
