      forgotSquareRoot: "Потерян корень: собственные значения AᵀA — квадраты σ², а норма Фробениуса — корень из суммы квадратов.",
      onlyNextValue: "Это σₖ₊₁, ошибка в 2-норме. В норме Фробениуса учитывается каждое отброшенное сингулярное число: √(σₖ₊₁² + …).",
      outerProductOrder: "Это v₁u₁ᵀ, транспонированная. Часть ранга 1 — σ₁u₁v₁ᵀ: u₁ — столбец U, v₁ᵀ — строка Vᵀ.",
