      reactionNotHalved: "Фирма 2 максимизирует (a − c − q₁ − q₂)q₂, поэтому её лучший ответ — половина остатка: q₂ = (a − c − q₁)/2.",
      orderAsPMinusOne: "p − 1 кратно порядку (Ферма), но не всегда равно ему: выпишите g, g², g³, … и остановитесь на первой степени, равной 1.",
      orderStoppedAtMinusOne: "Эта степень равна −1, то есть p − 1, а не 1: продолжайте; степени вернутся к 1 через вдвое больше шагов.",
