      overlapCountedTwice: "Отрезки перекрываются: мера объединения считает перекрытие один раз. Длины складываются, только когда части не пересекаются.",
      oneGapPerStep: "Каждый шаг удаляет середину каждого оставшегося отрезка, а не одного: число отрезков каждый шаг удваивается, а оставшаяся длина умножается на 1 − q.",
